const item = $input.first().json;
if (item.error) {
  console.log('Topic history fetch failed, continuing with empty history:', item.error);
  return { json: { topics: [] } };
}
if (!Array.isArray(item.topics)) {
  console.log('Topic history response missing topics array, defaulting to empty');
  return { json: { topics: [] } };
}
return { json: { topics: item.topics } };

const response = $input.first().json;
if (response.error) { throw new Error('OpenAI API error: ' + JSON.stringify(response.error)); }
const choice = (response.choices || [])[0];
let raw = (choice && choice.message && choice.message.content ? choice.message.content : '').trim();
if (!raw) {
  if (choice && choice.finish_reason === 'length') {
    throw new Error('Claude: Generate Topic hit max_completion_tokens before producing any text - reasoning likely consumed the whole budget. Increase max_completion_tokens on the "Claude: Generate Topic" node.');
  }
  throw new Error('OpenAI did not return topic candidates - check the Generate Topic node (finish_reason: ' + (choice && choice.finish_reason) + ')');
}
raw = raw.replace(/^```(?:\w*)?\s*/i, '').replace(/```\s*$/, '').trim();

// Parse the ranked candidate list; fall back to treating the whole thing as one topic.
let candidates = [];
try {
  const s = raw.indexOf('{'); const e = raw.lastIndexOf('}');
  const obj = JSON.parse(raw.slice(s, e + 1));
  candidates = Array.isArray(obj.candidates) ? obj.candidates : [];
} catch (err) {
  candidates = [{ topic: raw.replace(/^["']|["']$/g, ''), reason: 'unparsed fallback', score: 50 }];
}
candidates = candidates
  .filter(c => c && c.topic && String(c.topic).trim().length >= 10)
  .map(c => ({ topic: String(c.topic).trim(), reason: String(c.reason || ''), score: Number(c.score) || 0 }))
  .sort((a, b) => b.score - a.score);
if (!candidates.length) { throw new Error('No usable topic candidates parsed from: ' + raw.slice(0, 200)); }

// Hard dedup: skip candidates too similar to a recently-used topic (the prompt
// already dedups softly; this is the safety net).
const used = (($('Ensure Topics Array').item.json.topics) || []).map(t => String((t && t.topic) || '').toLowerCase()).filter(Boolean);
const words = s => s.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 3);
function tooSimilar(topic) {
  const tl = topic.toLowerCase();
  const w = new Set(words(topic));
  for (const u of used) {
    if (u && (u.includes(tl) || tl.includes(u))) return true;
    const uw = words(u);
    if (uw.length && uw.filter(x => w.has(x)).length / uw.length >= 0.6) return true;
  }
  return false;
}
const picked = candidates.find(c => !tooSimilar(c.topic)) || candidates[0];
return { json: { topic: picked.topic, score: picked.score, candidates } };

const response = $input.first().json;
if (response.error) {
  throw new Error('OpenAI API returned an error: ' + JSON.stringify(response.error));
}
const choice = (response.choices || [])[0];
let raw = choice?.message?.content;
if (!raw) throw new Error('OpenAI draft response missing choices[0].message.content');
if (choice.finish_reason === 'length') {
  throw new Error('OpenAI draft was cut off by max_completion_tokens - the script is likely truncated mid-JSON. Increase max_completion_tokens on the "Claude: Draft Script (Stage 1)" node.');
}

// Strip markdown code fences if present (the model sometimes wraps JSON in ```json ... ``` despite instructions not to)
raw = raw.trim();
if (raw.startsWith('```')) {
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
}
// Stage 1 is called with an assistant prefill of "{", so the model returns
// JSON only (no analysis preamble). Repair defensively: try the raw text,
// the prefill-completed text, and a balanced {...} extraction; use whichever
// first yields a valid object.
function extractJsonObject(s) {
  const at = s.indexOf('{');
  if (at === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = at; i < s.length; i++) {
    const cc = s.charCodeAt(i);
    if (inStr) {
      if (esc) esc = false;
      else if (cc === 92) esc = true;
      else if (cc === 34) inStr = false;
    } else if (cc === 34) inStr = true;
    else if (cc === 123) depth++;
    else if (cc === 125) { depth--; if (depth === 0) return s.slice(at, i + 1); }
  }
  return null;
}
function tryParse(s) {
  if (!s || typeof s !== 'string') return undefined;
  try { const v = JSON.parse(s); return (v && typeof v === 'object') ? v : undefined; } catch (e) { return undefined; }
}
const parsed = tryParse(raw) || tryParse('{' + raw) || tryParse(extractJsonObject('{' + raw)) || tryParse(extractJsonObject(raw));
if (!parsed) {
  throw new Error('OpenAI draft did not return valid JSON: ' + raw.slice(0, 300));
}
return { json: { draft: parsed } };

const response = $input.first().json;
if (response.error) {
  throw new Error('OpenAI API returned an error: ' + JSON.stringify(response.error));
}
const choice = (response.choices || [])[0];
let raw = choice?.message?.content;
if (!raw) throw new Error('OpenAI editor response missing choices[0].message.content');
if (choice.finish_reason === 'length') {
  throw new Error('OpenAI editorial rewrite was cut off by max_completion_tokens - likely truncated mid-JSON. Increase max_completion_tokens on the "Claude: Editorial Rewrite (Stage 2)" node.');
}
raw = raw.trim();
if (raw.startsWith('```')) {
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
}
// Stage 2 is called with an assistant prefill of "{", so the model returns
// JSON only (no analysis preamble). Repair defensively: try the raw text,
// the prefill-completed text, and a balanced {...} extraction; use whichever
// first yields a valid object.
function extractJsonObject(s) {
  const at = s.indexOf('{');
  if (at === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = at; i < s.length; i++) {
    const cc = s.charCodeAt(i);
    if (inStr) {
      if (esc) esc = false;
      else if (cc === 92) esc = true;
      else if (cc === 34) inStr = false;
    } else if (cc === 34) inStr = true;
    else if (cc === 123) depth++;
    else if (cc === 125) { depth--; if (depth === 0) return s.slice(at, i + 1); }
  }
  return null;
}
function tryParse(s) {
  if (!s || typeof s !== 'string') return undefined;
  try { const v = JSON.parse(s); return (v && typeof v === 'object') ? v : undefined; } catch (e) { return undefined; }
}
const parsed = tryParse(raw) || tryParse('{' + raw) || tryParse(extractJsonObject('{' + raw)) || tryParse(extractJsonObject(raw));
if (!parsed) {
  throw new Error('OpenAI editor did not return valid JSON: ' + raw.slice(0, 300));
}

const errors = [];
if (!parsed.hook || parsed.hook.length < 5 || parsed.hook.length > 200) {
  errors.push('hook missing or out of bounds (5-200 chars)');
}
if (parsed.hook_candidates !== undefined) {
  if (!Array.isArray(parsed.hook_candidates) || parsed.hook_candidates.length < 3 || parsed.hook_candidates.length > 6) {
    errors.push('hook_candidates, if present, must be an array of 3-6 strings');
  }
}
if (!parsed.title || parsed.title.length < 5 || parsed.title.length > 60) {
  errors.push('title missing or out of bounds (5-60 chars) - kept short for mobile-screen fit');
}
const validCaptionStyles = ['upbeat', 'serious', 'funny', 'neutral'];
if (!validCaptionStyles.includes(parsed.caption_style)) {
  errors.push('caption_style must be one of: ' + validCaptionStyles.join(', '));
}
const validTriggers = ['curiosity_gap', 'disbelief', 'fear_stakes', 'scale_shock', 'taboo_secret'];
if (!validTriggers.includes(parsed.trigger)) {
  errors.push('trigger must be one of: ' + validTriggers.join(', ') + ' - classify the hook honestly');
}
// Click-confirmation gate: the hook makes a promise; one scene must deliver it.
if (!parsed.payoff || typeof parsed.payoff !== 'object' || !parsed.payoff.claim || String(parsed.payoff.claim).trim().length < 5) {
  errors.push('payoff.claim missing - state the specific promise the hook makes so click-confirmation can be checked');
} else if (Array.isArray(parsed.scenes)) {
  const ris = Number(parsed.payoff.resolved_in_scene);
  if (!Number.isFinite(ris) || !parsed.scenes.some(s => Number(s.scene_index) === ris)) {
    errors.push('payoff.resolved_in_scene (' + parsed.payoff.resolved_in_scene + ') must match the scene_index of the scene that delivers the hook promise');
  }
}
if (!Array.isArray(parsed.tags) || parsed.tags.length < 5 || parsed.tags.length > 20) {
  // TAGS_AUTOFIX: tag count is a mechanical SEO field, not a creative
  // judgement. Repair it deterministically rather than spending script
  // attempts (and, once exhausted, the whole scheduled upload) on it.
  const _tagSeen = new Set();
  const _tagAdd = (v) => { const t = String(v || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim(); if (t.length >= 3 && t.length <= 30 && !_tagSeen.has(t)) _tagSeen.add(t); };
  (Array.isArray(parsed.tags) ? parsed.tags : []).forEach(_tagAdd);
  String(parsed.title || '').split(/\s+/).filter((w) => w.length > 3).forEach(_tagAdd);
  (Array.isArray(parsed.scenes) ? parsed.scenes : []).forEach((s) => _tagAdd(s && s.named_subject));
  ['facts', 'shorts', 'did you know', 'science facts', 'curiosity', 'interesting facts'].forEach(_tagAdd);
  parsed.tags = Array.from(_tagSeen).slice(0, 20);
  if (parsed.tags.length < 5) errors.push('tags could not be repaired to the required 5-20 strings');
}
if (!parsed.seo_description || parsed.seo_description.length < 20) {
  errors.push('seo_description missing or too short');
}
if (!parsed.comment_hook || parsed.comment_hook.length < 8) {
  errors.push('comment_hook missing or too short');
}
const genericCommentHooks = /^(what do you think|what.?s your take|thoughts\??$|comment below|let us know|drop a comment|tell us|do you agree|have you ever wondered|curious what you think)/i;
if (parsed.comment_hook && genericCommentHooks.test(parsed.comment_hook.trim())) {
  errors.push('comment_hook is too generic - must be specific to this exact fact, not a generic prompt');
}
if (parsed.comment_hook && !/\?\s*$/.test(parsed.comment_hook.trim())) {
  // COMMENT_HOOK_QUESTION_AUTOFIX: a missing '?' is a one-character format
  // slip, not a content problem - fix it deterministically instead of
  // burning a whole script-generation attempt (and, if repeated, the whole
  // scheduled run) over punctuation.
  parsed.comment_hook = parsed.comment_hook.trim().replace(/[.!,;:\s]+$/, '') + '?';
}

// Risky-visual keyword heuristic: catches shots that would need the AI video
// model to render readable text/numbers - the exact defect that made two
// prior videos look like obvious "AI slop" (garbled fake documents/money).
const riskyPatterns = [
  /readable/i, /legible/i, /visible text/i, /text visible/i, /showing the (total|amount|number|price)/i,
  /screen (showing|displaying)/i, /receipt (with|showing)/i, /document (with|showing)/i,
  /denomination/i, /close-?up of.*(document|receipt|form|paperwork).*text/i, /id card/i,
  /spreadsheet/i, /calculator display/i, /\$[0-9]/,
];

if (!Array.isArray(parsed.scenes) || parsed.scenes.length < 3 || parsed.scenes.length > 8) {
  errors.push('scenes must be an array of 3-8 items');
} else {
  let totalWords = 0;
  parsed.scenes.forEach((s, i) => {
    if (typeof s.scene_index !== 'number') errors.push(`scene ${i} missing numeric scene_index`);
    if (!s.point || s.point.length < 3) errors.push(`scene ${s.scene_index} missing point field`);
    if (!s.narration || s.narration.length < 5) errors.push(`scene ${s.scene_index} narration too short/missing`);
    if (Number(s.scene_index) === 0 && s.visual_source === 'template') errors.push(`scene ${s.scene_index} (scene_index 0, the first frame) must not be a template - it needs a real photo or video to stop the scroll before audio is understood`);
    if (s.visual_source !== 'template') {
      if (!s.visual_prompt || s.visual_prompt.length < 20) errors.push(`scene ${s.scene_index} visual_prompt too short/missing`);
      if (!s.negative_prompt) errors.push(`scene ${s.scene_index} missing negative_prompt`);
      if (!s.stock_search_query || s.stock_search_query.trim().length < 3) errors.push(`scene ${s.scene_index} missing stock_search_query`);
    }
    if (s.visual_source === 'template') {
      const spec = {"stat_reveal":["statValue","label"],"comparison":["leftLabel","leftValue","rightLabel","rightValue"],"kinetic_text":["line"]}[s.template_name];
      if (!spec) {
        errors.push(`scene ${s.scene_index} has unknown template_name "${s.template_name}" - must be one of stat_reveal, comparison, kinetic_text`);
      } else if (!s.template_data || typeof s.template_data !== 'object') {
        errors.push(`scene ${s.scene_index} missing template_data object`);
      } else {
        for (const field of spec) {
          if (!s.template_data[field] || String(s.template_data[field]).trim().length < 1) {
            errors.push(`scene ${s.scene_index} template_data missing required field "${field}" for template "${s.template_name}"`);
          }
        }
      }
    } else if (s.visual_source !== 'stock' && s.visual_source !== undefined) {
      errors.push(`scene ${s.scene_index} visual_source must be "stock" or "template", got "${s.visual_source}"`);
    }

    if (s.narration) totalWords += s.narration.trim().split(/\s+/).length;

    if (s.visual_source !== 'template' && s.visual_prompt) {
      for (const pattern of riskyPatterns) {
        if (pattern.test(s.visual_prompt)) {
          errors.push(`scene ${s.scene_index} visual_prompt likely requires readable text/numbers in the AI-generated video (matched pattern: ${pattern}) - this reliably renders as garbled fake text. Rewrite to show the concept without legible text.`);
          break;
        }
      }
    }
    if (s.visual_source !== 'template' && s.negative_prompt && !/text|legible|readable/i.test(s.negative_prompt)) {
      errors.push(`scene ${s.scene_index} negative_prompt does not explicitly exclude readable text/numbers - required for every scene`);
    }
  });

  const templateSceneCount = parsed.scenes.filter((s) => s.visual_source === 'template' && s.template_name !== 'annotated_real').length;
  if (templateSceneCount > 1) {
    errors.push(`script has ${templateSceneCount} Remotion template scenes - at most 1 is allowed; keep only the single most essential one and find a real photo/video proxy for every other beat`);
  }

  if (totalWords > 130) {
    errors.push(`total narration word count (${totalWords}) exceeds the 130 word hard ceiling (~40s Short) - the topic was too big for this format, cut genuine padding.`);
  } else if (totalWords < 30) {
    errors.push(`total narration word count (${totalWords}) is under the 30 word floor - too thin to be a real story.`);
  }
}


// Medical/health exclusion backstop - a best-effort keyword scan, not
// exhaustive, but catches obvious cases that slipped past both Claude passes.
const medicalKeywords = /\b(disease|illness|symptom|diagnos|treatment|medication|surgery|surgical|cancer|tumor|infection|virus|bacteria(?!l gut)|syndrome|disorder|therapy|prescription|patient|clinical|chronic pain|mental illness|depression|anxiety disorder|vaccine|antibiotic)\b/i;
const textToScan = [parsed.hook, parsed.title, ...(Array.isArray(parsed.scenes) ? parsed.scenes.map(s => s.narration || '') : [])].join(' ');
if (medicalKeywords.test(textToScan)) {
  errors.push('script appears to touch medical/health content (keyword match) - this content type is excluded, retry with a different topic');
}

// Topic-substitution backstop - a best-effort keyword-overlap heuristic, not
// exhaustive, but catches the confirmed production failure mode where
// Editorial Rewrite or Visual Director silently discards the selected topic
// and writes about something else entirely. A structurally valid substituted
// script passes every other check here, so without this it would silently
// publish under the wrong topic instead of failing loudly.
const seedTopic = String((($('Extract Generated Topic').item||{}).json||{}).topic||'');
const topicStopwords = new Set(['about','after','again','their','there','these','those','which','while','would','could','should','because','before','being','every','never','always','where','other','through','still','under','over']);
const significantWords = (s) => String(s||'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter((w) => w.length > 4 && !topicStopwords.has(w));
const seedTopicWords = new Set(significantWords(seedTopic));
if (seedTopicWords.size) {
  const scriptText = [parsed.hook, parsed.title, ...(Array.isArray(parsed.scenes) ? parsed.scenes.map((s) => s.narration || '') : [])].join(' ');
  const hasTopicOverlap = significantWords(scriptText).some((w) => seedTopicWords.has(w));
  if (!hasTopicOverlap) {
    errors.push(`script appears to be about a different topic than the one selected ("${seedTopic.slice(0, 100)}") - the topic must be edited, never replaced with a different one`);
  }
}

if (errors.length > 0) {
  return { json: { _scriptValid: false, _validationErrors: errors, _failedScript: parsed } };
}

// Append a SPOKEN outro as the final scene: a narrated share CTA over a
// branded end card. Voiced by the same TTS as the narration; flagged
// is_outro so compose renders the card (no burned captions) and excludes
// it from the mid-video comment_hook timing window.
const outroLine = (parsed.outro_line && String(parsed.outro_line).trim())
  ? String(parsed.outro_line).trim()
  : 'If this got you, send it to someone who needs to see it.';
if (Array.isArray(parsed.scenes) && parsed.scenes.length) {
  const maxIdx = parsed.scenes.reduce((m, s) => Math.max(m, Number(s.scene_index) || 0), -1);
  parsed.scenes.push({
    scene_index: maxIdx + 1,
    point: 'outro',
    narration: outroLine,
    visual_source: 'template',
    template_name: 'kinetic_text',
    template_data: { line: 'Like, Share, Follow', is_outro: true },
  });
}

return { json: { ...parsed, _scriptValid: true } };

const item = $input.item.json;
const sceneIndex = $('Split Out Scenes').item.json.scene_index;
if (!item?.video?.url) {
  throw new Error(`fal.ai result for scene_index ${sceneIndex} is missing video.url. Raw response: ` + JSON.stringify(item).slice(0, 500));
}
return { json: { scene_index: sceneIndex, video: item } };

const item = $input.item.json;
const sceneIndex = $('Split Out Scenes').item.json.scene_index;
if (!item?.audio_base64) {
  throw new Error(`ElevenLabs result for scene_index ${sceneIndex} is missing audio_base64. Raw response: ` + JSON.stringify(item).slice(0, 500));
}
if (!item?.alignment) {
  throw new Error(`ElevenLabs result for scene_index ${sceneIndex} is missing alignment/timestamps - check that the "with-timestamps" endpoint is being used. Raw response: ` + JSON.stringify(item).slice(0, 500));
}
return { json: { scene_index: sceneIndex, audio: item } };

// This node is downstream of a real Merge node with TWO input connections
// (images + audio), so n8n guarantees both branches have fully completed
// before this runs - no race condition from cross-branch $() references.
const allItems = $input.all().map(i => i.json);

// Each scene's visual asset is EITHER a generated image array (.images) OR a
// template scene descriptor (.visual_source === 'template') - shape-detect
// on whichever field is present.
const imageAgg = allItems.find(i => Array.isArray(i.data) && i.data[0] && (i.data[0].images || i.data[0].video_url || i.data[0].visual_source === 'template'));
const audioAgg = allItems.find(i => Array.isArray(i.data) && i.data[0] && i.data[0].audio);

if (!imageAgg) throw new Error('Could not find the visual branch in merged input - check "Aggregate All Videos" output shape');
if (!audioAgg) throw new Error('Could not find the audio branch in merged input - check "Aggregate All Audio" output shape');

const visuals = imageAgg.data;
const audios = audioAgg.data;

const merged = visuals.map((v) => {
  const match = audios.find((a) => a.scene_index === v.scene_index);
  if (!match) {
    throw new Error(`No audio found for scene_index ${v.scene_index} - visual/audio counts likely mismatched`);
  }
  return {
    scene_index: v.scene_index,
    images: v.images,
    video_url: v.video_url,
    source_duration: v.source_duration,
    source_width: v.source_width,
    source_height: v.source_height,
    visual_source: v.visual_source,
    template_name: v.template_name,
    template_data: v.template_data,
    audio: match.audio,
  };
});

merged.sort((a, b) => a.scene_index - b.scene_index);

return {
  json: {
    hook: $('Validate Final Script').item.json.hook,
    comment_hook: $('Validate Final Script').item.json.comment_hook,
    full_script: $('Validate Final Script').item.json.full_script,
    caption_style: $('Validate Final Script').item.json.caption_style,
    data: merged
  }
};

const item = $input.first().json;
if (item.success !== true) {
  throw new Error('FFmpeg compose service reported failure: ' + (item.error || 'unknown error') + ' | job_id: ' + (item.job_id || 'unknown'));
}
if (!item.output_path) {
  throw new Error('FFmpeg compose response missing output_path even though success=true: ' + JSON.stringify(item).slice(0, 500));
}
return { json: item };

// Reset the run-scoped retry counter. Workflow static data persists
// ACROSS executions (not just within one), so this must run once at the
// start of every execution or a stale count could leak in from a prior run.
$getWorkflowStaticData('node').scriptAttempt = 0;
return $input.all();

// Workflow static data, not $('NodeName').item back-reference: the loop-back
// edge routes through "Claude: Generate Topic", an independent HTTP call that
// does not reliably carry paired-item lineage back to this node's own prior
// run, so $('Increment Script Attempt').item silently fails to resolve across
// iterations and this counter gets stuck re-reading Init's one-time value
// forever - confirmed live: 5 full retry cycles, scriptAttempt=1 every time.
const staticData = $getWorkflowStaticData('node');
const newAttempt = (staticData.scriptAttempt || 0) + 1;
staticData.scriptAttempt = newAttempt;
const errors = $input.first().json._validationErrors || [];
console.log(`Script validation failed on attempt ${newAttempt}: ${errors.join(' | ')}`);
return { json: { scriptAttempt: newAttempt, lastErrors: errors } };

const scene = $('Split Out Scenes').item.json;
return {
  json: {
    scene_index: scene.scene_index,
    visual_source: 'template',
    template_name: scene.template_name,
    template_data: scene.template_data,
  }
};

const r = $json;
const sceneIndex = $('Split Out Scenes').item.json.scene_index;
if (!r || r.ok !== true || !r.url) { throw new Error('Tag B-roll: no asset for scene ' + sceneIndex); }
const out = { scene_index: sceneIndex, _source: r.source || 'broll', _attribution: r.attribution || '' };
if (r.type === 'video') { out.video_url = r.url; } else { out.images = [r.url]; }
return { json: out };

const DAY = 86400000;
// measure up to YESTERDAY (today is partial and drags averages down)
const end = new Date(Date.now() - DAY);
const start = new Date(end.getTime() - 27 * DAY); // 28-day window
const iso = (d) => d.toISOString().slice(0, 10);
return { json: { startDate: iso(start), endDate: iso(end) } };
